# Strategy: emit a short free-form preamble, then transition into a single
# naturally opened final verified span. Maintain durable state with phase,
# inside_span, and closed_spans. In free-form reasoning, use ordinary
# unconstrained steps while delimiters are masked. Once answer pressure or
# budget pressure appears, switch to nudged unconstrained steps until a left
# delimiter is emitted. Inside the span, only step under the positive guard
# helpers.IsComplete(generated) or helpers.CanConstrain(generated), using
# AppendConstrainedOrRightDelimiterStep so a complete expression can close with
# a right delimiter. After the first closed span, terminate.
# CSD_RATIONALE_END
phase = "reason"
inside_span = False
closed_spans = 0
freeform_steps = 0
nudge_steps = 0

# invariant helpers.lm == lm
# invariant helpers.parser == parser
# invariant lm.ValidTokensIdsLogits()
# invariant 0 <= stepsLeft <= maxSteps
# invariant |generated| + stepsLeft <= maxSteps
# decreases stepsLeft
while stepsLeft > 0:
    if inside_span:
        if helpers.IsComplete(generated) or helpers.CanConstrain(generated):
            generated, stepsLeft = helpers.AppendConstrainedOrRightDelimiterStep(prompt, generated, stepsLeft)
            if helpers.EndsWithRightDelimiter(generated):
                inside_span = False
                closed_spans = closed_spans + 1
                phase = "done"
                break
        else:
            break
    elif phase == "reason":
        if closed_spans > 0:
            phase = "done"
            break
        if freeform_steps >= 6:
            phase = "answer"
            break
        if not helpers.HasBudget(stepsLeft, 4):
            phase = "answer"
            break
        generated, stepsLeft = helpers.AppendUnconstrainedStep(prompt, generated, stepsLeft)
        freeform_steps = freeform_steps + 1
        if freeform_steps >= 3 and not helpers.HasBudget(stepsLeft, 6):
            phase = "answer"
    elif phase == "answer":
        if helpers.EndsWithLeftDelimiter(generated):
            inside_span = True
            break
        generated, stepsLeft = helpers.AppendUnconstrainedNudgeLeftDelimiterStep(prompt, generated, stepsLeft)
        nudge_steps = nudge_steps + 1
        if helpers.EndsWithLeftDelimiter(generated):
            inside_span = True
        elif nudge_steps >= 3 and not helpers.HasBudget(stepsLeft, 2):
            break
    else:
        break

